var a = [];
var b = [];
var c = [];
var d = [];
var e = [];
var colors;
var n;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	smooth();

	n = 200;

	for(let i = 0; i < n; i++) {
		a.push(new Particle(random(width), random(height)));
		b.push(new Particle(random(width), random(height)));
		c.push(new Particle(random(width), random(height)));
		d.push(new Particle(random(width), random(height)));
		e.push(new Particle(random(width), random(height)));
	}
}

function draw() {

	noStroke();

	colors = [color("#E2D6EA"), color("#FFD602"), color("#9966CB"), color("#7F6ADF"), color("#CE98F0"), color("#3A2D72"), color("#A060D8"), color("#110A1C"), color("#A060D8")]


	for(let i = 0; i < n; i++) {
		var alpha = map(i, 0, n, 0, 255);

		fill(color("#E2D6EA"));
		a[i].display();
		a[i].move();
		a[i].checkEdges();

		fill(color("#FFD602"));
		b[i].display();
		b[i].move();
		b[i].checkEdges();

		fill(color("#9966CB"));
		c[i].display();
		c[i].move();
		c[i].checkEdges();

		fill(color("#7F6ADF"));
		d[i].display();
		d[i].move();
		d[i].checkEdges();

		fill(color("#CE98F0"));
		e[i].display();
		e[i].move();
		e[i].checkEdges();
	}
}

function mousePressed() {
	setup();
}

class Particle {
	constructor(x, y) {
		this.pos = createVector(x, y);
		this.vel = createVector();
	}

	move() {
		let angle = noise(this.pos.y/400, this.pos.x/400) * TAU * 100;
		this.vel.set(sin(angle)*0.6, cos(angle)*0.6);
		this.pos.add(this.vel);
	}

	display() {
		ellipse(this.pos.x, this.pos.y, 2, 2);
	}

	checkEdges() {
		if(this.pos.x > width || this.pos.x < 0 || this.pos.y > height || this.pos.y < 0)
			this.pos.set(random(width), random(height));
	}

}

